        private void GridControl_Loaded(object sender, RoutedEventArgs e)
        {
            var grid = sender as GridControl;
            if (grid?.View is TableView tableView)
            {
                var descriptionColumn = grid.Columns.FirstOrDefault(c => c.FieldName == "Description");
                if (descriptionColumn != null)
                {
                    double maxWidth = 0;

                    // Loop through all visible rows
                    for (int i = 0; i < grid.VisibleRowCount; i++)
                    {
                        int rowHandle = grid.GetRowHandleByVisibleIndex(i);
                        if (rowHandle != DataControlBase.InvalidRowHandle)
                        {
                            var cellValue = grid.GetCellValue(rowHandle, descriptionColumn);
                            if (cellValue != null)
                            {
                                double textWidth = MeasureTextWidth(cellValue.ToString());
                                maxWidth = Math.Max(maxWidth, textWidth);
                            }
                        }
                    }

                    // Set the column width based on the maximum required width
                    descriptionColumn.Width = maxWidth + 20; // Add padding
                }
            }
        }



        // Helper function to measure text width
        private double MeasureTextWidth(string text)
        {
            var formattedText = new FormattedText(
                text,
                System.Globalization.CultureInfo.CurrentCulture,
                FlowDirection.LeftToRight,
                new Typeface("Segoe UI"),
                14, // Font size (adjust as needed)
                Brushes.Black,
                new NumberSubstitution(),
                TextFormattingMode.Display
            );

            return formattedText.Width;
        }

    }
